'use strict';
// SRWE: VLAN и trunk, маршрутизация между VLAN, DHCPv4, статическая маршрутизация.

const LESSON_NEXT_HOPS = ['10.0.12.2', '10.0.13.3', '10.0.14.4', '172.16.0.2', '172.16.1.2', '192.0.2.1', '198.51.100.1', '203.0.113.9'];

lessonDef({
  id: 'vlan', topic: 'vlan', minutes: 14,
  title: T('VLANs & trunks', 'VLAN и trunk', 'רשתות VLAN ו-trunk'),
  goal: T('Why VLANs exist, access ports, 802.1Q trunks, the native VLAN, DTP modes and the commands to check them.',
    'Зачем нужны VLAN, access-порты, trunk 802.1Q, native VLAN, режимы DTP и команды проверки.',
    'למה צריך VLAN, פורטי access, ‏trunk ‏802.1Q, ‏native VLAN, מצבי DTP והפקודות לבדיקה.'),
  sections: [
    lSec(['Why VLANs?', 'Зачем нужны VLAN', 'למה צריך VLAN'],
      lP(['A switch is one broadcast domain: a broadcast reaches every port. VLANs split one physical switch into several logical ones; each VLAN is its own broadcast domain and normally its own IP subnet.',
        'Коммутатор — один широковещательный домен: broadcast приходит во все порты. VLAN делят физический коммутатор на несколько логических; каждый VLAN — свой широковещательный домен и обычно своя IP-подсеть.',
        'מתג הוא תחום broadcast אחד: שידור לכולם מגיע לכל הפורטים. רשתות VLAN מחלקות מתג פיזי אחד לכמה מתגים לוגיים; כל VLAN הוא תחום broadcast נפרד ובדרך כלל גם תת-רשת IP נפרדת.']),
      lUL([
        ['Security — HR traffic is kept away from guests.', 'Безопасность — трафик отдела кадров отделён от гостей.', 'אבטחה — התעבורה של משאבי אנוש מופרדת מהאורחים.'],
        ['Less broadcast traffic, better performance.', 'Меньше широковещательного трафика, выше производительность.', 'פחות תעבורת broadcast, ביצועים טובים יותר.'],
        ['Users grouped by role, not by where they sit.', 'Пользователи сгруппированы по роли, а не по месту.', 'משתמשים מקובצים לפי תפקיד ולא לפי מיקום.'],
      ]),
      lP(['VLAN 1 is the default: every port starts in it and it cannot be deleted. Normal range 1–1005, extended 1006–4094. Hosts in different VLANs need a Layer 3 device to talk.',
        'VLAN 1 — по умолчанию: все порты изначально в нём, удалить его нельзя. Обычный диапазон 1–1005, расширенный 1006–4094. Хостам из разных VLAN для общения нужно устройство 3-го уровня.',
        'VLAN 1 הוא ברירת המחדל: כל הפורטים מתחילים בו ואי אפשר למחוק אותו. טווח רגיל 1–1005, מורחב 1006–4094. מארחים ב-VLAN שונים צריכים התקן שכבה 3 כדי לתקשר.'])),
    lSec(['Creating VLANs and access ports', 'Создание VLAN и access-порты', 'יצירת VLAN ופורטי access'],
      lCode('S1(config)# vlan 10\nS1(config-vlan)# name Sales\nS1(config-vlan)# exit\nS1(config)# interface fa0/1\nS1(config-if)# switchport mode access\nS1(config-if)# switchport access vlan 10\nS1(config-if)# exit\nS1(config)# interface range fa0/2 - 5\nS1(config-if-range)# switchport mode access\nS1(config-if-range)# switchport access vlan 10'),
      lP(['An access port belongs to exactly one VLAN and connects an end device; its frames are untagged.', 'Access-порт принадлежит ровно одному VLAN и подключает оконечное устройство; кадры на нём без тегов.', 'פורט access שייך ל-VLAN אחד בדיוק ומחבר התקן קצה; המסגרות בו ללא תג.']),
      lTip(['Assigning a port to a VLAN that does not exist creates the VLAN automatically (without a name).', 'Если назначить порт в несуществующий VLAN, коммутатор сам создаст этот VLAN (без имени).', 'שיוך פורט ל-VLAN שלא קיים יוצר את ה-VLAN אוטומטית (בלי שם).'])),
    lSec(['Trunks and 802.1Q', 'Trunk и 802.1Q', 'Trunk ו-802.1Q'],
      lP(['A trunk carries many VLANs over one link. The switch inserts an 802.1Q tag (4 bytes with the VLAN ID) into each frame.',
        'Trunk передаёт много VLAN по одному каналу. Коммутатор вставляет в каждый кадр тег 802.1Q (4 байта с номером VLAN).',
        'Trunk מעביר הרבה VLAN על קישור אחד. המתג מכניס לכל מסגרת תג 802.1Q ‏(4 בתים עם מספר ה-VLAN).']),
      lCode('S1(config)# interface g0/1\nS1(config-if)# switchport mode trunk\nS1(config-if)# switchport trunk native vlan 99\nS1(config-if)# switchport trunk allowed vlan 10,20,99'),
      lUL([
        ['Native VLAN — crosses the trunk untagged; default VLAN 1; must match on both ends.', 'Native VLAN — идёт по trunk без тега; по умолчанию VLAN 1; должен совпадать на обоих концах.', 'Native VLAN — עובר ב-trunk בלי תג; ברירת מחדל VLAN 1; חייב להיות זהה בשני הצדדים.'],
        ['Allowed VLANs — which VLANs may cross the trunk (all by default).', 'Allowed VLANs — какие VLAN пропускаются (по умолчанию все).', 'Allowed VLANs — אילו VLAN מותר להעביר ב-trunk (כברירת מחדל כולם).'],
      ])),
    lSec(['DTP', 'DTP', 'DTP'],
      lTable([['Side A', 'Сторона A', 'צד A'], ['Side B', 'Сторона B', 'צד B'], ['Result', 'Итог', 'תוצאה']], [
        ['dynamic auto', 'dynamic auto', ['Access — no trunk!', 'Access — trunk не поднимется!', 'Access — אין trunk!']],
        ['dynamic auto', 'dynamic desirable', 'Trunk'],
        ['dynamic desirable', 'dynamic desirable', 'Trunk'],
        ['trunk', 'auto / desirable', 'Trunk'],
        ['trunk', 'access', ['Mismatch — does not work', 'Несовпадение — не работает', 'אי-התאמה — לא עובד']],
      ]),
      lTip(['Best practice: "switchport mode trunk" on both ends and "switchport nonegotiate" to turn DTP off.', 'Хорошая практика: «switchport mode trunk» на обоих концах и «switchport nonegotiate», чтобы выключить DTP.', 'נוהג מומלץ: "switchport mode trunk" בשני הצדדים ו-"switchport nonegotiate" כדי לכבות את DTP.'])),
    lSec(['Verifying', 'Проверка', 'בדיקה'],
      lUL([
        ['show vlan brief — VLANs and their access ports (trunk ports are not listed).', 'show vlan brief — VLAN и их access-порты (trunk-порты не показываются).', 'show vlan brief — רשתות VLAN ופורטי ה-access שלהן (פורטי trunk לא מוצגים).'],
        ['show interfaces trunk — trunks, native VLAN, allowed VLANs.', 'show interfaces trunk — trunk, native VLAN, разрешённые VLAN.', 'show interfaces trunk — trunks, ‏native VLAN, ‏VLAN מותרים.'],
        ['show interfaces fa0/1 switchport — mode and VLAN of one port.', 'show interfaces fa0/1 switchport — режим и VLAN одного порта.', 'show interfaces fa0/1 switchport — המצב וה-VLAN של פורט אחד.'],
      ])),
  ],
  quiz: [
    lQ(['Each VLAN is a separate…', 'Каждый VLAN — это отдельный…', 'כל VLAN הוא…'], [['Broadcast domain', 'широковещательный домен', 'תחום broadcast נפרד'], ['Physical switch', 'физический коммутатор', 'מתג פיזי'], ['Routing table', 'таблица маршрутизации', 'טבלת ניתוב'], ['Cable', 'кабель', 'כבל']], 0,
      ['Broadcasts stay inside their VLAN.', 'Broadcast не выходит за пределы своего VLAN.', 'Broadcast נשאר בתוך ה-VLAN שלו.']),
    lQ(['Which is the default VLAN?', 'Какой VLAN по умолчанию?', 'מהו ה-VLAN של ברירת המחדל?'], ['VLAN 1', 'VLAN 0', 'VLAN 99', 'VLAN 1005'], 0,
      ['All ports start in VLAN 1.', 'Все порты изначально в VLAN 1.', 'כל הפורטים מתחילים ב-VLAN 1.']),
    lQ(['Which command puts an access port into VLAN 20?', 'Какая команда помещает access-порт в VLAN 20?', 'איזו פקודה משייכת פורט access ל-VLAN 20?'], ['switchport access vlan 20', 'vlan 20 access', 'switchport trunk vlan 20', 'ip vlan 20'], 0,
      ['Together with switchport mode access.', 'Вместе с switchport mode access.', 'יחד עם switchport mode access.']),
    lQ(['What does 802.1Q add to a frame on a trunk?', 'Что 802.1Q добавляет в кадр на trunk?', 'מה 802.1Q מוסיף למסגרת ב-trunk?'], [['A tag with the VLAN ID', 'Тег с номером VLAN', 'תג עם מספר ה-VLAN'], ['A new IP header', 'Новый IP-заголовок', 'כותרת IP חדשה'], ['A second MAC address', 'Второй MAC-адрес', 'כתובת MAC שנייה'], ['A password', 'Пароль', 'סיסמה']], 0,
      ['A 4-byte tag.', 'Тег в 4 байта.', 'תג של 4 בתים.']),
    lQ(['How are native VLAN frames sent over a trunk?', 'Как кадры native VLAN идут по trunk?', 'איך נשלחות מסגרות ה-native VLAN ב-trunk?'], [['Untagged', 'Без тега', 'בלי תג'], ['Tagged with VLAN 1', 'С тегом VLAN 1', 'עם תג VLAN 1'], ['Dropped', 'Отбрасываются', 'נזרקות'], ['Encrypted', 'Зашифрованными', 'מוצפנות']], 0,
      ['That is why the native VLAN must match on both ends.', 'Поэтому native VLAN должен совпадать на обоих концах.', 'לכן ה-native VLAN חייב להיות זהה בשני הצדדים.']),
    lQ(['Both ends of a link are "dynamic auto". What happens?', 'Оба конца канала — «dynamic auto». Что будет?', 'שני צדי הקישור במצב "dynamic auto". מה יקרה?'], [['It stays an access link — no trunk', 'Останется access — trunk не поднимется', 'הקישור נשאר access — אין trunk'], ['A trunk forms', 'Поднимется trunk', 'נוצר trunk'], ['Ports go err-disabled', 'Порты уйдут в err-disabled', 'הפורטים עוברים ל-err-disabled'], ['It depends on speed', 'Зависит от скорости', 'תלוי במהירות']], 0,
      ['Both sides wait passively.', 'Обе стороны пассивно ждут.', 'שני הצדדים מחכים באופן פסיבי.']),
    lQ(['Which command shows which access ports are in which VLAN?', 'Какая команда показывает, какие access-порты в каком VLAN?', 'איזו פקודה מראה אילו פורטי access נמצאים באיזה VLAN?'], ['show vlan brief', 'show ip route', 'show ip interface brief', 'show cdp neighbors'], 0,
      ['Trunks: show interfaces trunk.', 'Trunk — show interfaces trunk.', 'Trunks — ‏show interfaces trunk.']),
    lQ(['PCs in VLAN 10 and VLAN 20 on the same switch cannot ping. Why?', 'ПК в VLAN 10 и VLAN 20 на одном коммутаторе не пингуются. Почему?', 'מחשבים ב-VLAN 10 וב-VLAN 20 באותו מתג לא מצליחים לעשות ping. למה?'], [['Different VLANs need a Layer 3 device', 'Разным VLAN нужно устройство 3-го уровня', 'VLAN שונים צריכים התקן שכבה 3'], ['The switch is broken', 'Коммутатор сломан', 'המתג תקול'], ['A cross-over cable is needed', 'Нужен перекрёстный кабель', 'צריך כבל מוצלב'], ['STP blocks them', 'Их блокирует STP', 'STP חוסם אותם']], 0,
      ['That is expected — use inter-VLAN routing.', 'Так и должно быть — нужна маршрутизация между VLAN.', 'זה צפוי — צריך ניתוב בין VLAN.']),
  ],
});

