lessonDef({
  id: 'intervlan', topic: 'intervlan', minutes: 16,
  title: T('Inter-VLAN Routing', 'Маршрутизация между VLAN', 'ניתוב בין רשתות VLAN'),
  goal: T('Why VLANs need a router, router-on-a-stick with subinterfaces, the path of a packet, Layer 3 switches (IPv4 and IPv6) and typical mistakes.',
    'Зачем VLAN нужен маршрутизатор, router-on-a-stick с подынтерфейсами, путь пакета, коммутаторы 3-го уровня (IPv4 и IPv6) и типичные ошибки.',
    'למה VLAN צריכים נתב, router-on-a-stick עם תת-ממשקים, הדרך של חבילה, מתגי שכבה 3 ‏(IPv4 ו-IPv6) וטעויות נפוצות.'),
  sections: [
    lSec(['Three ways', 'Три способа', 'שלוש דרכים'],
      lUL([
        ['Legacy — one router interface and cable per VLAN. Wastes ports.', 'Классический — по интерфейсу роутера и кабелю на VLAN. Тратит порты.', 'הדרך הוותיקה — ממשק נתב וכבל לכל VLAN. מבזבז פורטים.'],
        ['Router-on-a-stick — one trunk to the router, one subinterface per VLAN.', 'Router-on-a-stick — один trunk к роутеру, по подынтерфейсу на VLAN.', 'Router-on-a-stick — ‏trunk אחד לנתב ותת-ממשק לכל VLAN.'],
        ['Layer 3 switch — SVIs per VLAN plus "ip routing". Fastest.', 'Коммутатор 3-го уровня — SVI на каждый VLAN и «ip routing». Самый быстрый.', 'מתג שכבה 3 — ‏SVI לכל VLAN ו-"ip routing". המהיר ביותר.'],
      ])),
    lSec(['Router-on-a-stick', 'Router-on-a-stick', 'Router-on-a-stick'],
      lCode('! Switch: the port to the router is a trunk\nS1(config)# interface g0/1\nS1(config-if)# switchport mode trunk\n\n! Router: one subinterface per VLAN\nR1(config)# interface g0/0\nR1(config-if)# no shutdown\nR1(config-if)# interface g0/0.10\nR1(config-subif)# encapsulation dot1Q 10\nR1(config-subif)# ip address 192.168.10.1 255.255.255.0\nR1(config-subif)# interface g0/0.20\nR1(config-subif)# encapsulation dot1Q 20\nR1(config-subif)# ip address 192.168.20.1 255.255.255.0'),
      lUL([
        ['"encapsulation dot1Q 10" ties the subinterface to VLAN 10; the number after the dot is only a name.', '«encapsulation dot1Q 10» привязывает подынтерфейс к VLAN 10; номер после точки — просто имя.', '"encapsulation dot1Q 10" קושר את תת-הממשק ל-VLAN 10; המספר אחרי הנקודה הוא רק שם.'],
        ['"no shutdown" on the physical interface brings up all subinterfaces.', '«no shutdown» на физическом интерфейсе поднимает все подынтерфейсы.', '"no shutdown" בממשק הפיזי מפעיל את כל תת-הממשקים.'],
        ['Each PC\'s gateway = the IP of its VLAN\'s subinterface.', 'Шлюз каждого ПК = IP подынтерфейса его VLAN.', 'השער של כל מחשב = כתובת ה-IP של תת-הממשק של ה-VLAN שלו.'],
      ])),
    lSec(['The path of a packet', 'Путь пакета', 'הדרך של חבילה'],
      lP(['PC1 (VLAN 10) pings PC2 (VLAN 20): frame to gateway 192.168.10.1 → tagged VLAN 10 on the trunk → router receives on g0/0.10, routes to g0/0.20 → back down tagged VLAN 20 → switch delivers to PC2. The packet crosses the trunk twice.',
        'PC1 (VLAN 10) пингует PC2 (VLAN 20): кадр на шлюз 192.168.10.1 → по trunk с тегом VLAN 10 → роутер принимает на g0/0.10 и маршрутизирует в g0/0.20 → обратно вниз с тегом VLAN 20 → коммутатор доставляет PC2. Пакет проходит trunk дважды.',
        'PC1 ‏(VLAN 10) עושה ping ל-PC2 ‏(VLAN 20): מסגרת לשער 192.168.10.1 → ב-trunk עם תג VLAN 10 → הנתב מקבל ב-g0/0.10 ומנתב ל-g0/0.20 → חזרה למטה עם תג VLAN 20 → המתג מוסר ל-PC2. החבילה עוברת ב-trunk פעמיים.'])),
    lSec(['Layer 3 switch', 'Коммутатор 3-го уровня', 'מתג שכבה 3'],
      lCode('MLS(config)# ip routing\nMLS(config)# interface vlan 10\nMLS(config-if)# ip address 192.168.10.1 255.255.255.0\nMLS(config-if)# interface vlan 20\nMLS(config-if)# ip address 192.168.20.1 255.255.255.0'),
      lP(['Without "ip routing" the switch does not route between SVIs. (NetTrainer uses router-on-a-stick.)', 'Без «ip routing» коммутатор не маршрутизирует между SVI. (В NetTrainer — router-on-a-stick.)', 'בלי "ip routing" המתג לא מנתב בין ה-SVI. (ב-NetTrainer משתמשים ב-router-on-a-stick.)'])),
    lSec(['IPv6 on a Layer 3 switch', 'IPv6 на коммутаторе 3-го уровня', 'IPv6 במתג שכבה 3'],
      lP(['A Layer 3 switch routes IPv6 the same way as IPv4: between SVIs (interface vlan) or routed ports (no switchport), in hardware (ASIC/TCAM) at port speed. The catch: IPv6 routing is off by default, and on some models it also depends on the SDM template.',
        'Коммутатор 3-го уровня маршрутизирует IPv6 так же, как IPv4: между SVI (interface vlan) или routed-портами (no switchport), аппаратно (ASIC/TCAM), на скорости портов. Подвох: по умолчанию маршрутизация IPv6 выключена, а на части моделей она ещё зависит от SDM-шаблона.',
        'מתג שכבה 3 מנתב IPv6 בדיוק כמו IPv4: בין ממשקי SVI ‏(interface vlan) או פורטים מנותבים (no switchport), בחומרה (ASIC/TCAM) במהירות הפורטים. המלכודת: ניתוב IPv6 כבוי כברירת מחדל, ובחלק מהדגמים הוא תלוי גם בתבנית ה-SDM.']),
      lCode('MLS(config)# sdm prefer dual-ipv4-and-ipv6 default   ! only if the platform needs it, then reload\nMLS(config)# ipv6 unicast-routing\nMLS(config)# interface vlan 10\nMLS(config-if)# ipv6 address 2001:db8:10::1/64\nMLS(config-if)# interface vlan 20\nMLS(config-if)# ipv6 address 2001:db8:20::1/64',
        ['Minimal example: two VLANs with IPv6 gateways on the switch.', 'Минимальный пример: два VLAN со шлюзами IPv6 на коммутаторе.', 'דוגמה מינימלית: שני VLAN עם שערי IPv6 במתג.']),
      lUL([
        ['Without "ipv6 unicast-routing" the switch is only an IPv6 host: it can have an address for management, but it does not forward traffic between networks and sends no RAs. A classic CCNA trap.', 'Без «ipv6 unicast-routing» коммутатор для IPv6 — просто хост: адрес для управления у него может быть, но трафик между сетями он не пересылает и RA не отправляет. Классическая ловушка CCNA.', 'בלי "ipv6 unicast-routing" המתג הוא רק מארח IPv6: יכולה להיות לו כתובת לניהול, אבל הוא לא מעביר תעבורה בין רשתות ולא שולח RA. מלכודת קלאסית ב-CCNA.'],
        ['"ip routing" (IPv4) and "ipv6 unicast-routing" (IPv6) are two separate commands — one does not turn on the other.', '«ip routing» (IPv4) и «ipv6 unicast-routing» (IPv6) — две разные команды, одна не включает другую.', '"ip routing" ‏(IPv4) ו-"ipv6 unicast-routing" ‏(IPv6) הן שתי פקודות נפרדות — אחת לא מפעילה את השנייה.'],
        ['Some platforms need an SDM template with IPv6 — e.g. older Catalyst 2960/3560/3750: sdm prefer dual-ipv4-and-ipv6 default, then reload. Without it IPv6 is not handled in hardware or the commands are missing. Template names differ by model — check show sdm prefer.', 'Части платформ нужен SDM-шаблон с IPv6 — например, старым Catalyst 2960/3560/3750: sdm prefer dual-ipv4-and-ipv6 default, затем перезагрузка. Без него IPv6 не обрабатывается в железе или команд вообще нет. Названия шаблонов зависят от модели — смотрите show sdm prefer.', 'חלק מהפלטפורמות צריכות תבנית SDM עם IPv6 — למשל Catalyst 2960/3560/3750 ישנים: sdm prefer dual-ipv4-and-ipv6 default ואז reload. בלעדיה IPv6 לא מטופל בחומרה או שהפקודות בכלל חסרות. שמות התבניות שונים לפי דגם — בודקים ב-show sdm prefer.'],
        ['Hosts learn their gateway from the RA (Router Advertisement), not from DHCP. The gateway on the hosts is usually the link-local address of the SVI (fe80::…), not the global one.', 'Хосты узнают шлюз из RA (Router Advertisement), а не из DHCP. Шлюзом на хостах обычно становится link-local адрес SVI (fe80::…), а не глобальный.', 'המארחים לומדים את השער מ-RA ‏(Router Advertisement), לא מ-DHCP. השער אצל המארחים הוא בדרך כלל כתובת ה-link-local של ה-SVI ‏(fe80::…), ולא הכתובת הגלובלית.'],
        ['Cheap or old "L3-lite" switches may support only static IPv6 routes, without OSPFv3. Check the datasheet before saying in an interview that a switch "can do everything".', 'Дешёвые или старые «L3-lite» коммутаторы могут поддерживать только статическую маршрутизацию IPv6, без OSPFv3. Прежде чем сказать на собеседовании, что коммутатор «умеет всё», загляните в datasheet.', 'מתגי "L3-lite" זולים או ישנים עשויים לתמוך רק בנתיבי IPv6 סטטיים, בלי OSPFv3. לפני שאומרים בראיון שמתג "יודע הכול" — בודקים ב-datasheet.'],
      ]),
      lTip(['Each host pings its own SVI, but pings between VLANs fail? First check: show running-config | include ipv6 unicast-routing.', 'Каждый хост пингует свой SVI, а между VLAN ping не проходит? Первым делом: show running-config | include ipv6 unicast-routing.', 'כל מארח עושה ping ל-SVI שלו, אבל ping בין VLAN נכשל? קודם כול: show running-config | include ipv6 unicast-routing.'])),
    lSec(['Typical mistakes', 'Типичные ошибки', 'טעויות נפוצות'],
      lUL([
        ['The switch port to the router is not a trunk.', 'Порт коммутатора к роутеру не trunk.', 'הפורט במתג שמחובר לנתב אינו trunk.'],
        ['Wrong VLAN number in encapsulation dot1Q.', 'Неверный VLAN в encapsulation dot1Q.', 'מספר VLAN שגוי ב-encapsulation dot1Q.'],
        ['The physical router interface is still shut down.', 'Физический интерфейс роутера всё ещё выключен.', 'הממשק הפיזי של הנתב עדיין כבוי.'],
        ['A PC has the wrong gateway or is in the wrong VLAN.', 'У ПК неверный шлюз или он не в том VLAN.', 'למחשב יש שער שגוי או שהוא ב-VLAN הלא נכון.'],
      ])),
  ],
  quiz: [
    lQ(['What do hosts in different VLANs need to communicate?', 'Что нужно хостам из разных VLAN для общения?', 'מה צריכים מארחים ב-VLAN שונים כדי לתקשר?'], [['A Layer 3 device', 'Устройство 3-го уровня', 'התקן שכבה 3'], ['Only a trunk', 'Только trunk', 'רק trunk'], ['A hub', 'Хаб', 'רכזת'], ['The same native VLAN', 'Одинаковый native VLAN', 'אותו native VLAN']], 0,
      ['Different VLANs = different subnets.', 'Разные VLAN = разные подсети.', 'VLAN שונים = תת-רשתות שונות.']),
    lQ(['In router-on-a-stick, the switch port to the router must be…', 'В router-on-a-stick порт коммутатора к роутеру должен быть…', 'ב-router-on-a-stick הפורט במתג שמחובר לנתב חייב להיות…'], [['A trunk', 'trunk', 'trunk'], ['Access in VLAN 1', 'access в VLAN 1', 'access ב-VLAN 1'], ['Shut down', 'выключен', 'כבוי'], ['Access in the native VLAN', 'access в native VLAN', 'access ב-native VLAN']], 0,
      ['One link carries all VLANs.', 'Один канал несёт все VLAN.', 'קישור אחד נושא את כל ה-VLAN.']),
    lQ(['Which command ties a subinterface to VLAN 30?', 'Какая команда привязывает подынтерфейс к VLAN 30?', 'איזו פקודה קושרת תת-ממשק ל-VLAN 30?'], ['encapsulation dot1Q 30', 'switchport access vlan 30', 'vlan 30', 'interface g0/0.30'], 0,
      ['The subinterface name alone does not choose the VLAN.', 'Само имя подынтерфейса VLAN не выбирает.', 'השם של תת-הממשק לבד לא בוחר את ה-VLAN.']),
    lQ(['The gateway of a PC in VLAN 20 should be…', 'Шлюз ПК в VLAN 20 — это…', 'השער של מחשב ב-VLAN 20 צריך להיות…'], [['The router subinterface for VLAN 20', 'Подынтерфейс роутера для VLAN 20', 'תת-הממשק של הנתב עבור VLAN 20'], ['The physical interface g0/0', 'Физический интерфейс g0/0', 'הממשק הפיזי g0/0'], ['The switch IP in VLAN 1', 'IP коммутатора в VLAN 1', 'ה-IP של המתג ב-VLAN 1'], ['Another PC', 'Другой ПК', 'מחשב אחר']], 0,
      ['Each VLAN has its own gateway.', 'У каждого VLAN свой шлюз.', 'לכל VLAN שער משלו.']),
    lQ(['Subinterfaces are set but g0/0 is "administratively down". Fix?', 'Подынтерфейсы настроены, но g0/0 «administratively down». Что делать?', 'תת-הממשקים מוגדרים אבל g0/0 במצב "administratively down". מה עושים?'], [['no shutdown on g0/0', 'no shutdown на g0/0', 'no shutdown ב-g0/0'], ['Put an IP on g0/0', 'Назначить IP на g0/0', 'להגדיר IP ב-g0/0'], ['Replace the cable', 'Заменить кабель', 'להחליף כבל'], ['Create VLANs on the router', 'Создать VLAN на роутере', 'ליצור VLAN בנתב']], 0,
      ['Subinterfaces depend on the physical interface.', 'Подынтерфейсы зависят от физического интерфейса.', 'תת-הממשקים תלויים בממשק הפיזי.']),
    lQ(['Which command enables routing between SVIs on a Layer 3 switch?', 'Какая команда включает маршрутизацию между SVI на коммутаторе L3?', 'איזו פקודה מפעילה ניתוב בין SVI במתג שכבה 3?'], ['ip routing', 'router rip', 'switchport mode trunk', 'encapsulation dot1Q'], 0,
      ['Without it SVIs are only management interfaces.', 'Без неё SVI — только интерфейсы управления.', 'בלעדיה ה-SVI הם רק ממשקי ניהול.']),
    lQ(['How many times does inter-VLAN traffic cross the trunk in router-on-a-stick?', 'Сколько раз трафик между VLAN проходит trunk в router-on-a-stick?', 'כמה פעמים תעבורה בין VLAN עוברת ב-trunk ב-router-on-a-stick?'], [['Twice', 'Дважды', 'פעמיים'], ['Once', 'Один раз', 'פעם אחת'], ['Never', 'Ни разу', 'אף פעם'], ['Four times', 'Четыре раза', 'ארבע פעמים']], 0,
      ['Up to the router and back down.', 'Вверх к роутеру и обратно вниз.', 'למעלה לנתב וחזרה למטה.']),
    lQ(['An L3 switch has IPv6 addresses on two SVIs. Each host pings its own SVI, but pings between VLANs fail. What do you check first?', 'На L3-коммутаторе IPv6-адреса на двух SVI. Каждый хост пингует свой SVI, но между VLAN ping не проходит. Что проверите первым?', 'במתג L3 מוגדרות כתובות IPv6 בשני SVI. כל מארח עושה ping ל-SVI שלו, אבל ping בין VLAN נכשל. מה בודקים קודם?'], [['Whether "ipv6 unicast-routing" is configured', 'Введена ли «ipv6 unicast-routing»', 'אם מוגדר "ipv6 unicast-routing"'], ['The trunk to the router', 'Trunk к роутеру', 'ה-trunk לנתב'], ['The DNS server', 'DNS-сервер', 'שרת ה-DNS'], ['The DHCPv4 pool', 'Пул DHCPv4', 'מאגר ה-DHCPv4']], 0,
      ['Hosts reach their SVI, so L1/L2 are fine — the switch just does not route IPv6. IPv6 routing is off until "ipv6 unicast-routing".', 'Хосты достают до своего SVI, значит L1/L2 в порядке — коммутатор просто не маршрутизирует IPv6. Без «ipv6 unicast-routing» маршрутизация IPv6 выключена.', 'המארחים מגיעים ל-SVI שלהם, אז שכבות 1–2 תקינות — המתג פשוט לא מנתב IPv6. ניתוב IPv6 כבוי עד "ipv6 unicast-routing".']),
    lQ(['From which message do IPv6 hosts learn their default gateway?', 'Из какого сообщения IPv6-хосты узнают шлюз по умолчанию?', 'מאיזו הודעה מארחי IPv6 לומדים את שער ברירת המחדל?'], [['Router Advertisement (RA)', 'Router Advertisement (RA)', 'Router Advertisement ‏(RA)'], ['DHCP Offer', 'DHCP Offer', 'DHCP Offer'], ['ARP reply', 'Ответ ARP', 'תשובת ARP'], ['OSPFv3 Hello', 'OSPFv3 Hello', 'OSPFv3 Hello']], 0,
      ['DHCPv6 has no gateway option — the gateway always comes from the RA.', 'В DHCPv6 нет опции шлюза — шлюз всегда приходит из RA.', 'ב-DHCPv6 אין אופציה לשער — השער תמיד מגיע מה-RA.']),
    lQ(['Which address do IPv6 hosts usually use as their default gateway?', 'Какой адрес IPv6-хосты обычно используют как шлюз?', 'באיזו כתובת מארחי IPv6 משתמשים בדרך כלל כשער ברירת מחדל?'], [['The link-local (fe80::…) address of the router or SVI', 'Link-local адрес (fe80::…) роутера или SVI', 'כתובת ה-link-local ‏(fe80::…) של הנתב או ה-SVI'], ['The global address, e.g. 2001:db8:10::1', 'Глобальный адрес, например 2001:db8:10::1', 'הכתובת הגלובלית, למשל 2001:db8:10::1'], ['ff02::1', 'ff02::1', 'ff02::1'], ['::1', '::1', '::1']], 0,
      ['The RA is sent from the link-local address, so hosts take it as the gateway. ff02::1 = all nodes, ::1 = loopback.', 'RA отправляется с link-local адреса, поэтому хосты берут его как шлюз. ff02::1 — все узлы, ::1 — loopback.', 'ה-RA נשלח מכתובת ה-link-local, ולכן המארחים לוקחים אותה כשער. ‏ff02::1 = כל הצמתים, ‏::1 = loopback.']),
    lQ(['On an older Catalyst 3560 the "ipv6 address" commands are missing. What may be needed?', 'На старом Catalyst 3560 нет команд «ipv6 address». Что может понадобиться?', 'ב-Catalyst 3560 ישן חסרות הפקודות "ipv6 address". מה עשוי להידרש?'], [['An SDM template with IPv6 (sdm prefer dual-ipv4-and-ipv6 default) and a reload', 'SDM-шаблон с IPv6 (sdm prefer dual-ipv4-and-ipv6 default) и перезагрузка', 'תבנית SDM עם IPv6 ‏(sdm prefer dual-ipv4-and-ipv6 default) ו-reload'], ['ip routing', 'ip routing', 'ip routing'], ['switchport mode trunk on all ports', 'switchport mode trunk на всех портах', 'switchport mode trunk בכל הפורטים'], ['A DHCPv6 pool', 'Пул DHCPv6', 'מאגר DHCPv6']], 0,
      ['The SDM template decides how TCAM memory is split; without an IPv6 template the switch cannot handle IPv6. The new template works only after a reload.', 'SDM-шаблон определяет, как делится память TCAM; без шаблона с IPv6 коммутатор не умеет работать с IPv6. Новый шаблон начинает действовать только после перезагрузки.', 'תבנית ה-SDM קובעת איך מחולק זיכרון ה-TCAM; בלי תבנית עם IPv6 המתג לא יודע לטפל ב-IPv6. התבנית החדשה נכנסת לתוקף רק אחרי reload.']),
    lQ(['"ip routing" is on and IPv4 routes fine between VLANs. Is IPv6 routed too?', '«ip routing» включена, IPv4 между VLAN маршрутизируется. А IPv6?', '"ip routing" פעיל ו-IPv4 מנותב בין VLAN. האם גם IPv6 מנותב?'], [['No — IPv6 needs its own "ipv6 unicast-routing"', 'Нет — для IPv6 нужна отдельная «ipv6 unicast-routing»', 'לא — ל-IPv6 צריך "ipv6 unicast-routing" נפרד'], ['Yes, "ip routing" covers both', 'Да, «ip routing» включает оба', 'כן, "ip routing" מכסה את שניהם'], ['Only for link-local addresses', 'Только для link-local адресов', 'רק עבור כתובות link-local'], ['Only after "no switchport"', 'Только после «no switchport»', 'רק אחרי "no switchport"']], 0,
      ['The two protocols are switched on separately.', 'Протоколы включаются по отдельности.', 'שני הפרוטוקולים מופעלים בנפרד.']),
  ],
  gen: [
    function genSubif(rng) {
      const v = rng.pick([10, 20, 30, 40, 50, 60, 70, 99, 100, 110]), third = rng.int(1, 250), gw = '192.168.' + third + '.1', w = rng.pick([1, 5, 11, 21]);
      return lGen(T('VLAN ' + v + ' uses 192.168.' + third + '.0/24, gateway ' + gw + '. Which config creates its gateway on router-on-a-stick?',
        'VLAN ' + v + ' использует 192.168.' + third + '.0/24, шлюз ' + gw + '. Какая конфигурация создаёт для него шлюз на router-on-a-stick?',
        'VLAN ' + v + ' משתמש ב-192.168.' + third + '.0/24 עם שער ' + gw + '. איזו תצורה יוצרת לו שער ב-router-on-a-stick?'),
        'interface g0/0.' + v + '\n encapsulation dot1Q ' + v + '\n ip address ' + gw + ' 255.255.255.0',
        ['interface g0/0.' + v + '\n encapsulation dot1Q ' + w + '\n ip address ' + gw + ' 255.255.255.0',
          'interface g0/0.' + v + '\n switchport access vlan ' + v + '\n ip address ' + gw + ' 255.255.255.0',
          'interface g0/0.' + v + '\n encapsulation dot1Q ' + v + '\n ip address 192.168.' + third + '.0 255.255.255.0'],
        T('It needs "encapsulation dot1Q ' + v + '" and the gateway address ' + gw + ' (not the network address).', 'Нужны «encapsulation dot1Q ' + v + '» и адрес шлюза ' + gw + ' (а не адрес сети).', 'צריך "encapsulation dot1Q ' + v + '" ואת כתובת השער ' + gw + ' (ולא את כתובת הרשת).'));
    },
  ],
});

