lessonDef({
  id: 'static', topic: 'static', minutes: 14,
  title: T('IP Static Routing', 'Статическая маршрутизация', 'ניתוב סטטי'),
  goal: T('The routing table, static and default routes, longest prefix match, administrative distance and floating static routes.',
    'Таблица маршрутизации, статические маршруты и маршрут по умолчанию, самый длинный префикс, административное расстояние и плавающие маршруты.',
    'טבלת הניתוב, נתיבים סטטיים ונתיב ברירת מחדל, התאמת הקידומת הארוכה ביותר, מרחק מנהלי ונתיבים סטטיים צפים.'),
  sections: [
    lSec(['The routing table', 'Таблица маршрутизации', 'טבלת הניתוב'],
      lUL([
        ['C and L — connected networks and the router\'s own addresses, added automatically.', 'C и L — подключённые сети и собственные адреса маршрутизатора, появляются сами.', 'C ו-L — רשתות מחוברות והכתובות של הנתב עצמו, נוספים אוטומטית.'],
        ['S — static routes typed by the administrator.', 'S — статические маршруты, введённые вручную.', 'S — נתיבים סטטיים שהמנהל הקליד.'],
        ['R = RIP, O = OSPF — learned dynamically.', 'R — RIP, O — OSPF — получены динамически.', 'R = RIP, ‏O = OSPF — נלמדו באופן דינמי.'],
      ]),
      lCode('R1# show ip route\nGateway of last resort is 10.0.0.2 to network 0.0.0.0\n\nC    10.0.0.0/30 is directly connected, GigabitEthernet0/1\nL    10.0.0.1/32 is directly connected, GigabitEthernet0/1\nC    192.168.1.0/24 is directly connected, GigabitEthernet0/0\nL    192.168.1.1/32 is directly connected, GigabitEthernet0/0\nS    192.168.2.0/24 [1/0] via 10.0.0.2\nS*   0.0.0.0/0 [1/0] via 10.0.0.2', ['[1/0] = [administrative distance / metric]', '[1/0] = [административное расстояние / метрика]', '‏[1/0] = [מרחק מנהלי / מטריקה]'])),
    lSec(['Static and default routes', 'Статические маршруты и маршрут по умолчанию', 'נתיבים סטטיים ונתיב ברירת מחדל'],
      lCode('R1(config)# ip route 192.168.2.0 255.255.255.0 10.0.0.2     ! next-hop IP\nR1(config)# ip route 192.168.2.0 255.255.255.0 g0/1         ! exit interface\nR1(config)# ip route 0.0.0.0 0.0.0.0 10.0.0.2               ! default route'),
      lTip(['Routing must work both ways: every router needs a route to every remote network, including the way back.', 'Маршрутизация нужна в обе стороны: каждому роутеру нужен маршрут к каждой удалённой сети, включая обратный путь.', 'הניתוב חייב לעבוד בשני הכיוונים: כל נתב צריך נתיב לכל רשת מרוחקת, כולל הדרך חזרה.'])),
    lSec(['Longest prefix match', 'Самый длинный префикс', 'התאמת הקידומת הארוכה ביותר'],
      lCode('S  10.1.0.0/16 via 10.0.12.2\nS  10.1.5.0/24 via 10.0.13.3\nS* 0.0.0.0/0   via 10.0.14.4\n\n10.1.5.9  -> /24 -> 10.0.13.3\n10.1.7.1  -> /16 -> 10.0.12.2\n8.8.8.8   -> /0  -> 10.0.14.4'),
      lP(['If several routes match, the most specific one (longest prefix) wins.', 'Если подходят несколько маршрутов, побеждает самый точный (самый длинный префикс).', 'אם כמה נתיבים מתאימים, הנתיב הספציפי ביותר (הקידומת הארוכה ביותר) מנצח.'])),
    lSec(['Administrative distance', 'Административное расстояние', 'מרחק מנהלי'],
      lTable([['Source', 'Источник', 'מקור'], 'AD'], [
        [['Connected', 'Подключённая', 'מחוברת'], '0'], [['Static', 'Статический', 'סטטי'], '1'], ['EIGRP', '90'], ['OSPF', '110'], ['RIP', '120'],
      ]),
      lP(['Lower AD = more trusted, for the SAME prefix from different sources. A floating static route has a higher AD and is used only when the main route disappears.',
        'Меньше AD — больше доверия, для ОДНОГО И ТОГО ЖЕ префикса из разных источников. Плавающий статический маршрут имеет большее AD и используется, только когда пропадает основной.',
        'AD נמוך יותר = אמין יותר, עבור אותה קידומת ממקורות שונים. לנתיב סטטי צף יש AD גבוה יותר והוא משמש רק כשהנתיב הראשי נעלם.']),
      lCode('R1(config)# ip route 0.0.0.0 0.0.0.0 10.9.9.2 130   ! backup, AD 130')),
  ],
  quiz: [
    lQ(['Which code marks a directly connected network?', 'Каким кодом отмечена подключённая сеть?', 'איזה קוד מסמן רשת מחוברת ישירות?'], ['C', 'S', 'L', 'R'], 0,
      ['C connected, L local /32, S static, R RIP.', 'C — подключённая, L — local /32, S — статический, R — RIP.', 'C מחוברת, ‏L מקומית ‎/32, ‏S סטטי, ‏R ‏RIP.']),
    lQ(['What is the AD of a static route?', 'Какое AD у статического маршрута?', 'מהו ה-AD של נתיב סטטי?'], ['1', '0', '110', '120'], 0,
      ['Connected 0, static 1, OSPF 110, RIP 120.', 'Подключённая 0, статический 1, OSPF 110, RIP 120.', 'מחוברת 0, סטטי 1, ‏OSPF 110, ‏RIP 120.']),
    lQ(['R1 has a route to R2\'s LAN, but the ping still fails. What is likely missing?', 'У R1 есть маршрут к LAN за R2, но ping не проходит. Чего не хватает?', 'ל-R1 יש נתיב ל-LAN של R2, אבל ה-ping נכשל. מה כנראה חסר?'], [['A route on R2 back to R1\'s LAN', 'Обратного маршрута на R2', 'נתיב חזרה ב-R2 ל-LAN של R1'], ['A default gateway on R1', 'Шлюза на R1', 'שער ברירת מחדל ב-R1'], ['An IP on the switch', 'IP на коммутаторе', 'IP במתג'], ['A cross-over cable', 'Перекрёстного кабеля', 'כבל מוצלב']], 0,
      ['The reply needs a way back.', 'Ответу нужен обратный путь.', 'התשובה צריכה דרך חזרה.']),
    lQ(['Which command creates a default route on a router?', 'Какая команда создаёт маршрут по умолчанию на роутере?', 'איזו פקודה יוצרת נתיב ברירת מחדל בנתב?'], ['ip route 0.0.0.0 0.0.0.0 10.0.0.2', 'ip default-gateway 10.0.0.2', 'ip route 255.255.255.255 0.0.0.0 10.0.0.2', 'default route 10.0.0.2'], 0,
      ['ip default-gateway is for switches.', 'ip default-gateway — для коммутаторов.', 'ip default-gateway מיועד למתגים.']),
    lQ(['What is a floating static route?', 'Что такое плавающий статический маршрут?', 'מהו נתיב סטטי צף?'], [['A backup route with a higher AD', 'Резервный маршрут с большим AD', 'נתיב גיבוי עם AD גבוה יותר'], ['A route that moves between interfaces', 'Маршрут, который переходит между интерфейсами', 'נתיב שעובר בין ממשקים'], ['The route with the lowest AD', 'Маршрут с наименьшим AD', 'הנתיב עם ה-AD הנמוך ביותר'], ['A RIP route', 'Маршрут RIP', 'נתיב RIP']], 0,
      ['It is used only when the main route fails.', 'Используется, только когда основной пропадает.', 'הוא משמש רק כשהנתיב הראשי נופל.']),
    lQ(['What is an "L" route?', 'Что такое маршрут «L»?', 'מהו נתיב "L"?'], [['The router\'s own interface address as /32', 'Собственный адрес интерфейса как /32', 'הכתובת של ממשק הנתב עצמו כ-‎/32'], ['A LAN link', 'Канал к LAN', 'קישור ל-LAN'], ['A load-balanced route', 'Маршрут с балансировкой', 'נתיב עם איזון עומסים'], ['A loopback', 'Loopback', 'Loopback']], 0,
      ['L = local.', 'L — local.', 'L = local.']),
  ],
  gen: [
    function genLongestMatch(rng) {
      const a = rng.int(1, 250), b = rng.int(1, 250), c = rng.int(0, 15) * 16;
      const [h16, h24, h28, hDef] = rng.shuffle(LESSON_NEXT_HOPS).slice(0, 4);
      const routes = 'S  10.' + a + '.0.0/16 via ' + h16 + '\nS  10.' + a + '.' + b + '.0/24 via ' + h24 + '\nS  10.' + a + '.' + b + '.' + c + '/28 via ' + h28 + '\nS* 0.0.0.0/0 via ' + hDef;
      const kind = rng.int(0, 3);
      let dest, hop, why;
      if (kind === 0) { dest = '10.' + a + '.' + b + '.' + (c + rng.int(1, 14)); hop = h28; why = '/28'; }
      else if (kind === 1) { let x; do { x = rng.int(1, 254); } while (x >= c && x < c + 16); dest = '10.' + a + '.' + b + '.' + x; hop = h24; why = '/24'; }
      else if (kind === 2) { let y; do { y = rng.int(0, 255); } while (y === b); dest = '10.' + a + '.' + y + '.' + rng.int(1, 254); hop = h16; why = '/16'; }
      else { let z; do { z = rng.int(1, 250); } while (z === a); dest = rng.chance(0.5) ? '10.' + z + '.' + rng.int(0, 255) + '.' + rng.int(1, 254) : '8.8.' + rng.int(0, 8) + '.' + rng.int(1, 254); hop = hDef; why = '/0'; }
      const q = lGen(T('R1 has these routes. Which next hop does it use for a packet to ' + dest + '?', 'У R1 такие маршруты. Через какой next hop он отправит пакет на ' + dest + '?', 'ל-R1 יש את הנתיבים האלה. דרך איזה next hop הוא ישלח חבילה ל-' + dest + '?'),
        'via ' + hop, [h16, h24, h28, hDef].filter((x) => x !== hop).map((x) => 'via ' + x),
        T('The longest matching prefix wins: ' + why + '.', 'Побеждает самый длинный подходящий префикс: ' + why + '.', 'הקידומת התואמת הארוכה ביותר מנצחת: ' + why + '.'));
      q.code = routes;
      return q;
    },
    function genIpRoute(rng) {
      const len = rng.pick([24, 24, 25, 26, 27, 28]), size = Math.pow(2, 32 - len);
      const net = '192.168.' + rng.int(1, 250) + '.' + size * rng.int(0, 256 / size - 1), nh = rng.pick(LESSON_NEXT_HOPS), m = lenToMask(len);
      return lGen(T('The network ' + net + '/' + len + ' is behind R2. R2\'s address on the link to R1 is ' + nh + '. Which command do you enter on R1?',
        'Сеть ' + net + '/' + len + ' находится за R2. Адрес R2 на канале к R1 — ' + nh + '. Какую команду ввести на R1?',
        'הרשת ' + net + '/' + len + ' נמצאת מאחורי R2. הכתובת של R2 בקישור ל-R1 היא ' + nh + '. איזו פקודה מקלידים ב-R1?'),
        'ip route ' + net + ' ' + m + ' ' + nh, ['ip route ' + net + ' ' + lWild(len) + ' ' + nh, 'ip route ' + nh + ' ' + m + ' ' + net, 'ip route ' + net + '/' + len + ' ' + nh, 'ip default-gateway ' + nh],
        T('Syntax: ip route <destination network> <mask> <next hop>.', 'Синтаксис: ip route <сеть назначения> <маска> <next hop>.', 'תחביר: ip route <רשת יעד> <מסכה> <next hop>.'));
    },
  ],
});
